-- KSYS-14633 / DXM UK V2 sharing allowlist audit
-- AUDIT ONLY. Do not run MIGRATE_SHARING_POST_TYPES (DRY_RUN or LIVE).
-- Do not UPDATE sharing_settings or active_sitewide_plugins.
-- Scope: 45 V2 client prefixes x DEV / STG / PRD = 135 WP schemas from the DXM prod UK estate list.
-- Export this result as the ticket spreadsheet. Filter classification for:
--   NEEDS_MIGRATION
--   FIX_PLUGINS_FIRST

SELECT
  s.env,
  s.schema_name AS `schema`,
  s.instance_id AS client_instance,
  CASE
    WHEN s.has_jet_engine = 1 AND IFNULL(s.has_kurtosys_engine, 0) = 0 THEN 'Pass'
    ELSE 'Fail'
  END AS v2_plugins,
  CASE
    WHEN IFNULL(s.has_legacy_listing, 0) = 1 OR IFNULL(s.has_legacy_filters, 0) = 1 THEN 'Yes'
    ELSE 'No'
  END AS needs_allowlist_remap,
  CASE WHEN s.pre_rows > 0 THEN 'Yes' ELSE 'No' END AS already_migrated,
  CASE
    WHEN (IFNULL(s.has_legacy_listing, 0) = 1 OR IFNULL(s.has_legacy_filters, 0) = 1)
     AND s.has_jet_engine = 1 AND IFNULL(s.has_kurtosys_engine, 0) = 0 THEN 'NEEDS_MIGRATION'
    WHEN (IFNULL(s.has_legacy_listing, 0) = 1 OR IFNULL(s.has_legacy_filters, 0) = 1) THEN 'FIX_PLUGINS_FIRST'
    WHEN s.has_jet_engine = 1 AND IFNULL(s.has_kurtosys_engine, 0) = 0 THEN 'ALREADY_OK'
    ELSE 'INVESTIGATE'
  END AS classification,
  CONCAT_WS('; ',
    IF(s.sharing_rows = 0, 'no sharing_settings row', NULL),
    IF(s.sharing_rows > 1, CONCAT('duplicate sharing_settings rows=', s.sharing_rows), NULL),
    IF(s.has_legacy_listing = 1, 'legacy listing CPT kurtosys-engine still in sharing_settings', NULL),
    IF(s.has_legacy_filters = 1, 'legacy filters CPT ksys-smart-filters still in sharing_settings', NULL),
    IF(s.has_jet_listing = 1, 'jet-engine already present in sharing_settings', NULL),
    IF(s.has_jet_filters = 1, 'jet-smart-filters already present in sharing_settings', NULL),
    IF(s.has_kurtosys_engine = 1, 'stale kurtosys-engine still in active_sitewide_plugins', NULL),
    IF(IFNULL(s.has_jet_engine, 0) = 0, 'jet-engine not network-active', NULL),
    IF(s.plugin_rows = 0, 'no active_sitewide_plugins row', NULL),
    IF(s.pre_rows > 0, 'sharing_settings_pre_ksys14633 backup present', NULL),
    IF(
      IFNULL(s.has_kurtosys_blocks, 0)
    + IFNULL(s.has_kurtosys_elements, 0)
    + IFNULL(s.has_kurtosys_menu, 0)
    + IFNULL(s.has_kurtosys_smart_filters, 0)
    + IFNULL(s.has_kurtosys_tabs, 0) > 0,
      'other kurtosys-* plugins still network-active (note only, not the hard gate)',
      NULL
    )
  ) AS notes,
  s.sharing_rows,
  s.has_legacy_listing,
  s.has_legacy_filters,
  s.has_jet_listing,
  s.has_jet_filters,
  s.pre_rows,
  s.has_jet_engine,
  s.has_kurtosys_engine,
  s.has_jet_smart_filters,
  s.has_kurtosys_smart_filters,
  s.has_jet_blocks,
  s.has_kurtosys_blocks,
  s.has_jet_elements,
  s.has_kurtosys_elements,
  s.has_jet_menu,
  s.has_kurtosys_menu,
  s.has_jet_tabs,
  s.has_kurtosys_tabs
FROM (
SELECT
