  'cldnrdoswp_dev' AS schema_name,
  'cldnrdoswp' AS instance_id,
  (SELECT COUNT(*) FROM `cldnrdoswp_dev`._wpsitemeta WHERE site_id=1 AND meta_key='sharing_settings') AS sharing_rows,
  (SELECT MAX(meta_value LIKE '%kurtosys-engine%') FROM `cldnrdoswp_dev`._wpsitemeta WHERE site_id=1 AND meta_key='sharing_settings') AS has_legacy_listing,
