  (SELECT meta_value LIKE '%kurtosys-smart-filters/kurtosys-smart-filters.php%' FROM `cldnrdoswp_dev`._wpsitemeta WHERE site_id=1 AND meta_key='active_sitewide_plugins' LIMIT 1) AS has_kurtosys_smart_filters,
