  (SELECT meta_value LIKE '%jet-menu/jet-menu.php%' FROM `cldnrdoswp_dev`._wpsitemeta WHERE site_id=1 AND meta_key='active_sitewide_plugins' LIMIT 1) AS has_jet_menu,
